  const detail = { message: err.message };
  if (err.cause) {
    const c = err.cause;
    detail.cause = {
      message: c.message,
      code: c.code,
      errno: c.errno,
      syscall: c.syscall,
      hostname: c.hostname,
      address: c.address,
      port: c.port
    };
  }
  return detail;
}

async function fetchContacts(baseUrl, apiKey, userEmail) {
  const response = await fetch(`${baseUrl}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || `Failed to get contacts (HTTP ${response.status})`);
  }
  return data;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];
  const outputFile = args.output || 'contacts.txt';

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  // Candidate base URLs from the skill manifest and the skill's scripts/README.
  const candidates = [];
  if (args['base-url']) candidates.push(args['base-url']);
  candidates.push('https://agenskill-api.onrender.com');
  candidates.push('https://agenskill.onrender.com');

  let data = null;
  let usedBaseUrl = null;
  const failures = [];

  for (const baseUrl of candidates) {
    try {
      data = await fetchContacts(baseUrl, apiKey, userEmail);
      usedBaseUrl = baseUrl;
      break;
    } catch (err) {
      failures.push({ baseUrl, error: describeError(err) });
    }
  }

  if (!data) {
    throw new Error('All candidate API hosts failed: ' + JSON.stringify(failures));
  }

  const contacts = data.contacts || [];
  const lines = [];
  lines.push(`Contacts for ${userEmail}`);
  lines.push('='.repeat(60));
  lines.push('');
  if (contacts.length === 0) {
    lines.push('No contacts found.');
  } else {
    contacts.forEach((contact, i) => lines.push(formatContact(contact, i + 1)));
  }
  lines.push('');
  lines.push(`Total: ${contacts.length}`);

  fs.writeFileSync(outputFile, lines.join('\n'), 'utf8');

  console.log(JSON.stringify({
    success: true,
    baseUrl: usedBaseUrl,
    count: contacts.length,
    output: outputFile,
    contacts: contacts
  }, null, 2));
}

main().catch(err => {
