#!/usr/bin/env node
// Task-local script: list contacts via the email-api and save them to a txt file.
// Replicates .codex/skills/email-api/scripts/email-contacts.js using only Node built-ins,
// with resilience for transient DNS failures (retries, alternate DNS, DNS-over-HTTPS, direct IP).

const https = require('https');
const dns = require('dns');
const fs = require('fs');

const CANDIDATE_HOSTS = ['agenskill-api.onrender.com', 'agenskill.onrender.com'];

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (tok.startsWith('--')) {
      const key = tok.slice(2);
      const val = argv[i + 1];
      args[key] = val !== undefined && !val.startsWith('--') ? val : true;
      if (val !== undefined && !val.startsWith('--')) i++;
    }
  }
  return args;
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function formatContact(contact, index) {
  const id = contact.id !== undefined ? contact.id : '';
  const name = contact.name || '';
  const email = contact.email || '';
  const parts = [];
  if (name) parts.push(name);
  if (email) parts.push(email);
  const line = parts.join(' - ');
  const idSuffix = id !== '' ? ` [id: ${id}]` : '';
  return `${index}. ${line}${idSuffix}`;
}

async function fetchViaFetch(baseUrl, apiKey, userEmail, timeoutMs) {
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${baseUrl}/contacts`, {
      headers: { 'X-API-Key': apiKey, 'X-User-Email': userEmail },
      signal: controller.signal
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`);
    return data;
  } finally {
    clearTimeout(t);
  }
}

function requestWithIp(ip, hostname, apiKey, userEmail, timeoutMs) {
  return new Promise((resolve, reject) => {
    const req = https.request({
      host: ip,
      servername: hostname,
      path: '/contacts',
      method: 'GET',
      headers: { 'X-API-Key': apiKey, 'X-User-Email': userEmail, 'Host': hostname },
      timeout: timeoutMs,
      lookup: (h, opts, cb) => cb(null, ip, 4)
    }, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        try {
          const data = JSON.parse(body);
          if (res.statusCode >= 400) return reject(new Error(data.error || `HTTP ${res.statusCode}`));
          resolve(data);
        } catch (e) {
          reject(new Error(`Bad response from ${hostname}: ${body.slice(0, 200)}`));
        }
      });
    });
    req.on('timeout', () => req.destroy(new Error('Request timeout')));
    req.on('error', reject);
    req.end();
  });
}

function resolve4WithTimeout(host, timeoutMs) {
  return Promise.race([
    dns.resolve4(host),
    sleep(timeoutMs).then(() => { throw new Error('DNS resolve timeout'); })
  ]);
}

function dohQuery(ip, servername, path, timeoutMs) {
  return new Promise((resolve, reject) => {
    const req = https.request({
      host: ip,
      servername: servername,
      path: path,
      method: 'GET',
      headers: { 'Host': servername, 'Accept': 'application/dns-json' },
      timeout: timeoutMs,
      lookup: (h, opts, cb) => cb(null, ip, 4)
    }, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        try {
          const data = JSON.parse(body);
          if (res.statusCode >= 400) return reject(new Error(data.error || `DoH HTTP ${res.statusCode}`));
          resolve(data);
        } catch (e) {
          reject(new Error(`Bad DoH response: ${body.slice(0, 200)}`));
        }
      });
    });
    req.on('timeout', () => req.destroy(new Error('DoH timeout')));
    req.on('error', reject);
    req.end();
  });
}

async function resolveViaDoH(host, timeoutMs) {
  // Cloudflare DNS-over-HTTPS JSON API, connecting to the well-known 1.1.1.1 anycast address.
  const data = await dohQuery('1.1.1.1', 'cloudflare-dns.com', `/dns-query?name=${encodeURIComponent(host)}&type=A`, timeoutMs);
  const answers = (data.Answer || []).filter(a => a.type === 1 && a.data);
  return answers.map(a => a.data);
}

async function tryHost(host, apiKey, userEmail, failures) {
  const baseUrl = `https://${host}`;

  // 1) Plain fetch with retries (handles transient EAI_AGAIN).
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return { data: await fetchViaFetch(baseUrl, apiKey, userEmail, 20000), via: `fetch (${baseUrl})` };
    } catch (err) {
      failures.push(`fetch ${baseUrl} attempt ${attempt}: ${err.message}`);
      await sleep(1000 * attempt);
    }
  }

  // 2) Resolve via alternate DNS servers, then connect directly to the IP.
  try {
    dns.setServers(['1.1.1.1', '8.8.8.8']);
    const ips = await resolve4WithTimeout(host, 8000);
    for (const ip of ips) {
      try {
        return { data: await requestWithIp(ip, host, apiKey, userEmail, 20000), via: `direct IP ${ip} (${host})` };
      } catch (err) {
        failures.push(`direct IP ${ip} (${host}): ${err.message}`);
      }
    }
  } catch (err) {
    failures.push(`alt-DNS resolve ${host}: ${err.message}`);
  }

  // 3) DNS-over-HTTPS via Cloudflare, then connect directly to the resolved IP.
  try {
    const ips = await resolveViaDoH(host, 10000);
    for (const ip of ips) {
      try {
        return { data: await requestWithIp(ip, host, apiKey, userEmail, 20000), via: `direct IP ${ip} (${host}, DoH-resolved)` };
      } catch (err) {
        failures.push(`direct IP ${ip} (${host}, DoH-resolved): ${err.message}`);
      }
    }
    failures.push(`DoH resolve ${host}: no usable IPv4 answers`);
  } catch (err) {
    failures.push(`DoH resolve ${host}: ${err.message}`);
  }

  return null;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];
  const outputFile = args.output || 'contacts.txt';

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const hosts = args['base-url'] ? [args['base-url'].replace(/^https?:\/\//, '').replace(/\/$/, '')] : CANDIDATE_HOSTS;
  const failures = [];
  let result = null;
  let via = null;

  for (const host of hosts) {
    result = await tryHost(host, apiKey, userEmail, failures);
    if (result) { via = result.via; break; }
  }

  if (!result) {
    throw new Error('All candidate API hosts failed. Details: ' + JSON.stringify(failures));
  }

  const contacts = result.data.contacts || [];
  const lines = [];
  lines.push(`Contacts for ${userEmail}`);
  lines.push('='.repeat(60));
  lines.push('');
  if (contacts.length === 0) {
    lines.push('No contacts found.');
  } else {
    contacts.forEach((contact, i) => lines.push(formatContact(contact, i + 1)));
  }
  lines.push('');
  lines.push(`Total: ${contacts.length}`);

  fs.writeFileSync(outputFile, lines.join('\n'), 'utf8');

  console.log(JSON.stringify({
    success: true,
    via: via,
    count: contacts.length,
    output: outputFile,
    contacts: contacts
  }, null, 2));
}

main().catch(err => {
  console.error(JSON.stringify({ success: false, error: err.message }, null, 2));
  process.exit(1);
});
